import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"HTTP API & MCP","description":"","frontmatter":{},"headers":[],"relativePath":"guide/http.md","filePath":"guide/http.md","lastUpdated":1793030102000}'),o={name:"guide/http.md"};function c(r,e,d,l,p,i){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="http-api-mcp" tabindex="-1">HTTP API &amp; MCP <a class="header-anchor" href="#http-api-mcp" aria-label="Permalink to &quot;HTTP API &amp; MCP&quot;">​</a></h1><p><a href="/reference/http"><code>@chamvi/http</code></a> turns a chamvi app into one <a href="https://github.com/routup/routup" target="_blank" rel="noreferrer">routup</a> <code>App</code>: humans start and follow runs over REST and server-sent events, channels take deliveries at <code>/channels/&lt;name&gt;</code> (webhooks with bearer tokens, signed GitHub deliveries), and agents (OpenClaw, Claude, any MCP client) start runs as MCP tools. It also serves <code>/healthz</code>, <code>/readyz</code> and <code>/metrics</code>, and ships the graceful shutdown helper.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/http</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> auth = authenticators(verifier);</span></span>
<span class="line"><span style="color:#958A8B;">// POST /channels/webhook/&lt;agent&gt;&lt;path&gt;, authenticated with the same chain</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> webhooks = webhookChannel({ auth });</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#958A8B;">    // the channels read the store, agents and clock from the engine</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [httpChannel(), mcpChannel(), webhooks, cronChannel()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">let</span><span style="color:#E6DFDE;"> server: ReturnType&lt;</span><span style="color:#FF7B84;">typeof</span><span style="color:#E6DFDE;"> serve&gt; | undefined;</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> shutdown = createShutdown({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#958A8B;">    // the server is created after the app; the helper only calls close() at shutdown</span></span>
<span class="line"><span style="color:#E6DFDE;">    server: { close: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (force) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> { </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> server?.close(force); } },</span></span>
<span class="line"><span style="color:#E6DFDE;">    readinessDelayMs: </span><span style="color:#E7C58C;">5_000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> app = createHttpApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#E6DFDE;">    auth,</span></span>
<span class="line"><span style="color:#958A8B;">    // the channels served at /channels/&lt;name&gt;</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [webhooks],</span></span>
<span class="line"><span style="color:#E6DFDE;">    shutdown,</span></span>
<span class="line"><span style="color:#E6DFDE;">    basePath: </span><span style="color:#E7C58C;">&#39;/api&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // behind one reverse proxy: trust its X-Forwarded-For</span></span>
<span class="line"><span style="color:#E6DFDE;">    trustProxy: </span><span style="color:#E7C58C;">1</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    cors: { origin: </span><span style="color:#E7C58C;">&#39;https://chamvi.example.com&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// recovers runs, then starts every channel (the cron schedule among them)</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.start();</span></span>
<span class="line"><span style="color:#958A8B;">// srvx must not install its own signal handler</span></span>
<span class="line"><span style="color:#E6DFDE;">server = serve(app, { port: </span><span style="color:#E7C58C;">3000</span><span style="color:#E6DFDE;">, gracefulShutdown: </span><span style="color:#FF7B84;">false</span><span style="color:#E6DFDE;"> });</span></span></code></pre></div><p>Every HTTP or MCP start ends in <code>engine.dispatch()</code>; nothing runs synchronously in a request. Errors are always JSON <code>{ status, code, message, issues? }</code>, unmatched routes included; a 5xx body says <code>Internal Server Error</code> and the cause goes to <code>onError</code>. An issue carries the <code>received</code> value only when it is small (at most 256 characters as JSON), so a 400 for an oversized list, a long string or a large file never echoes the body back.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p>The package ships three channels; register them on the engine (<code>new Engine({ channels })</code>) like any other:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Subscription</th><th>Served at</th><th>Envelope</th></tr></thead><tbody><tr><td><code>httpChannel()</code>, <code>mcpChannel()</code></td><td><code>http.on({ schema? })</code> (id <code>http</code>, at most one per agent)</td><td><code>POST /agents/:name/runs</code>, MCP <code>run_&lt;name&gt;</code></td><td><code>trigger: &#39;http&#39;</code>, channel <code>http</code> (REST, UI) or <code>mcp</code></td></tr><tr><td><code>webhookChannel({ auth, name?, bodyLimit? })</code></td><td><code>webhook.on(path, { schema?, idempotencyKey?, concurrencyKey? })</code> (id <code>webhook:&lt;path&gt;</code>)</td><td><code>POST /channels/webhook/&lt;agent&gt;&lt;path&gt;</code></td><td><code>trigger: &#39;webhook:&lt;path&gt;&#39;</code>, channel <code>webhook</code></td></tr></tbody></table><p>An agent without <code>http.on()</code> answers 404 on REST and gets no MCP tool; the engine refuses the subscription unless it holds <code>httpChannel()</code>. The subscription&#39;s <code>schema</code> validates the payload; a failure answers 400 with <code>issues</code> and dispatches nothing. A webhook is served on its own path under the agent: <code>webhook.on(&#39;/issues&#39;)</code> on agent <code>intake</code> is <code>POST /channels/webhook/intake/issues</code> (a path of <code>/</code> is <code>/channels/webhook/intake</code>); <code>GET /agents</code> lists each <code>hook</code> URL. A delivery needs a principal of the channel&#39;s <code>auth</code> (one authenticator or a chain, required, since the app never authenticates channel routes) holding <code>agent:&lt;agent&gt;:run</code>, checked before the body is read; webhook runs carry no invoker.</p><p><code>createHttpApp({ channels })</code> mounts <code>POST /channels/&lt;name&gt;</code> and everything below it for exactly the listed channels: each needs an <code>in</code> and must be the object the engine holds under its name (<code>InvalidAgentDefinitionError</code> otherwise), and any other <code>/channels/...</code> path is 404. The mount is rate-limited but never authenticated by <code>auth</code>: each channel checks its own credentials. <code>in({ request, subpath }, ctx)</code> gets the raw request, its body unread (<code>readRequestBody(request, { limit })</code> from <code>@chamvi/http</code> reads it; above the limit it answers 413 and closes the connection), and the raw subpath (<code>&#39;&#39;</code> for the bare path, else starting with <code>/</code>, still percent-encoded). Its <code>Response</code> is sent as is; a thrown error renders like any route&#39;s error. See <a href="/guide/channels">Channels &amp; the Envelope</a>.</p><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method and path</th><th>Permission</th><th>Answer</th></tr></thead><tbody><tr><td><code>POST /agents/:name/runs</code></td><td><code>agent:&lt;name&gt;:run</code></td><td><code>202 { runId, deduplicated }</code>; body <code>{ payload?, idempotencyKey?, address?, attachments? }</code> (or an <code>Idempotency-Key</code> header); runs carry channel <code>http</code></td></tr><tr><td><code>GET /runs</code></td><td><code>run:read</code>, or <code>agent:&lt;agent&gt;:run</code> with <code>filter[agent]=&lt;agent&gt;</code></td><td><code>200 { data, meta: { total, limit, offset } }</code></td></tr><tr><td><code>GET /runs/:id</code></td><td><code>run:read</code> or <code>agent:&lt;run.agent&gt;:run</code></td><td>The run with its <code>steps</code></td></tr><tr><td><code>GET /runs/:id/stream</code></td><td>as <code>GET /runs/:id</code></td><td>SSE</td></tr><tr><td><code>GET /runs/:id/artifacts</code></td><td>as <code>GET /runs/:id</code></td><td><code>200 { data: Artifact[] }</code></td></tr><tr><td><code>GET /runs/:id/artifacts/:artifactId</code></td><td>as <code>GET /runs/:id</code></td><td>The bytes, as a download</td></tr><tr><td><code>POST /runs/:id/cancel</code></td><td><code>run:cancel</code></td><td><code>202 { runId, status }</code></td></tr><tr><td><code>POST /runs/:id/approve</code></td><td><code>agent:&lt;run.agent&gt;:approve</code></td><td><code>202 { runId, status: &#39;queued&#39; }</code>; body <code>{ approvalId, approved, reason? }</code>; answers the run&#39;s current wait point without a token (409 for another <code>approvalId</code>, an expired wait point or a run not waiting)</td></tr><tr><td><code>POST /channels/&lt;name&gt;[/...]</code></td><td>the channel&#39;s own</td><td>Whatever the channel&#39;s <code>in</code> answers; only for the channels in <code>channels</code></td></tr><tr><td><code>GET /agents</code>, <code>GET /schedules</code></td><td><code>run:read</code></td><td><code>{ data, issues }</code>: agent summaries and the <a href="/guide/agent-folders">agent folders</a> that failed to load (<code>{ agent, message, at }</code>); agent summaries list their subscriptions <code>{ channel, id, hook? }</code>; cron subscriptions with their channel and next fire time</td></tr><tr><td><code>GET /agents/:name/state/kv</code></td><td><code>state:read</code></td><td><code>200 { data: Array&lt;{ key, value }&gt; }</code> in key code-point order; <code>page[limit]</code> (default 50, at most 100), <code>page[offset]</code></td></tr><tr><td><code>GET</code>, <code>PATCH /agents/:name/state/kv/:key</code></td><td><code>state:read</code>, <code>state:write</code></td><td><code>{ key, value }</code></td></tr><tr><td><code>GET /agents/:name/state/collections/:collection</code></td><td><code>state:read</code></td><td>Documents (<code>{ id, ...fields }</code>, or <code>{ id, doc }</code> for a non-object); top-level equality filters (<code>filter[issue]=42</code> matches a number, <code>filter[issue]=&quot;42&quot;</code> the string; <code>filter[id]</code> is 400, <code>id</code> being the store id), <code>page[limit]</code> (no offset)</td></tr><tr><td><code>GET /me</code></td><td>authenticated</td><td><code>200 { id, kind, name?, permissions }</code>: the caller itself, with its own permissions</td></tr><tr><td><code>/mcp</code></td><td>authenticated</td><td>MCP endpoint</td></tr><tr><td><code>GET /healthz</code>, <code>/readyz</code>, <code>/metrics</code></td><td>none</td><td>Liveness, readiness, Prometheus</td></tr></tbody></table><p><code>GET /runs</code> takes rapiq&#39;s URL syntax: <code>filter[agent]=triage</code>, <code>filter[status]=queued,running</code>, <code>page[limit]</code> (default 50, at most 100), <code>page[offset]</code>, <code>sort=createdAt</code> (oldest first, the default) or <code>sort=-createdAt</code> (newest first). Bodies are JSON of at most <code>bodyLimit</code> bytes (default 1 MiB). A protected route checks the bearer token before it reads the body. Runs leave the API without their internal <code>claim</code>, and the run&#39;s invoker and a <code>wait</code> step&#39;s approver without their <code>permissions</code> (see <a href="#invoker">Invoker</a>).</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p><code>POST /agents/:name/runs</code> takes <code>attachments</code>: at most 16 objects <code>{ mediaType, filename?, data }</code>, <code>mediaType</code> of the form <code>type/subtype</code> (no parameters), <code>filename</code> 1 to 255 characters, <code>data</code> strict base64 (padded, standard alphabet, no whitespace). A bad entry answers 400 <code>validation_error</code> with the path of the field (<code>[&#39;attachments&#39;, 0, &#39;data&#39;]</code>) and dispatches nothing. Base64 travels in the JSON body, so <code>bodyLimit</code> (default 1 MiB) bounds the files too; raise it for larger ones. The files become <a href="/guide/channels#attachments">attachments</a> of the run.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> base = </span><span style="color:#E7C58C;">&#39;https://chamvi.example.com/api&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> headers = { authorization: </span><span style="color:#E7C58C;">\`Bearer </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">token</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;content-type&#39;</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">&#39;application/json&#39;</span><span style="color:#E6DFDE;"> };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> started = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> fetch(</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">base</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">/agents/triage/runs\`</span><span style="color:#E6DFDE;">, {</span></span>
<span class="line"><span style="color:#E6DFDE;">    method: </span><span style="color:#E7C58C;">&#39;POST&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    headers,</span></span>
<span class="line"><span style="color:#E6DFDE;">    body: JSON.stringify({</span></span>
<span class="line"><span style="color:#E6DFDE;">        payload: { issue: </span><span style="color:#E7C58C;">43</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">        // at most 16, data as strict base64; the whole body stays within bodyLimit</span></span>
<span class="line"><span style="color:#E6DFDE;">        attachments: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">            mediaType: </span><span style="color:#E7C58C;">&#39;image/png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            filename: </span><span style="color:#E7C58C;">&#39;crash.png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            data: Buffer.from(png).toString(</span><span style="color:#E7C58C;">&#39;base64&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">        }],</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> { runId } = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> started.json() </span><span style="color:#FF7B84;">as</span><span style="color:#E6DFDE;"> { runId: string };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// metadata of the attachments and of every file a tool stored</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> listed = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> fetch(</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">base</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">/runs/</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">runId</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">/artifacts\`</span><span style="color:#E6DFDE;">, { headers });</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> { data } = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> listed.json() </span><span style="color:#FF7B84;">as</span><span style="color:#E6DFDE;"> { data: Array&lt;{ id: string; mediaType: string }&gt; };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// the bytes, served as a download with the stored media type</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> [first] = data;</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> file = first ? </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> fetch(</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">base</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">/runs/</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">runId</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">/artifacts/</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">first</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">, { headers }) : </span><span style="color:#FF7B84;">undefined</span><span style="color:#E6DFDE;">;</span></span></code></pre></div><p><code>GET /runs/:id/artifacts</code> lists the run&#39;s artifacts (attachments and files its tools stored, see <a href="/guide/agents#files">Files</a>) as metadata. <code>GET /runs/:id/artifacts/:artifactId</code> answers the bytes with the stored media type as <code>content-type</code>, <code>content-length</code>, <code>content-disposition: attachment</code> (with <code>filename</code> and an RFC 5987 <code>filename*</code> when the artifact has a filename), <code>x-content-type-options: nosniff</code> and <code>cache-control: private, no-store</code>, so a stored HTML or SVG file is downloaded, never rendered in the API&#39;s origin. Both follow the run read rule (404 for an unknown run before 403); an unknown artifact, or one of another run, is 404 <code>artifact_not_found</code>.</p><h2 id="following-a-run" tabindex="-1">Following a run <a class="header-anchor" href="#following-a-run" aria-label="Permalink to &quot;Following a run&quot;">​</a></h2><p><code>GET /runs/:id/stream</code> sends <code>run.updated</code> with the current run, then each step as <code>step.appended</code> (<code>id</code> is the step index, so <code>Last-Event-ID</code> resumes), then live events; it ends once the run is <code>completed</code>, <code>failed</code> or <code>cancelled</code>. The engine&#39;s events only cover runs executing in this process, so the stream also polls the store every <code>stream.pollMs</code> (2 s) and sees a run that <a href="/guide/concurrency">another replica</a> executes; an idle poll sends <code>ping</code>. A client that disconnects unsubscribes at once, and the app ends open streams on shutdown.</p><p>While the model writes, the stream also sends <code>delta</code> events, <code>data: { step, kind, text }</code> with <code>kind</code> <code>text</code> or <code>reasoning</code> (the engine&#39;s <a href="/guide/execution#streaming"><code>run.delta</code></a>). <code>step</code> is the checkpoint step index of the <code>llm</code> step being generated (one per model call), not the <code>step.appended</code> <code>id</code>, which also counts <code>tool</code> and <code>wait</code> rows. They carry no <code>id</code>, so <code>Last-Event-ID</code> stays a step index, and they are live only: a reconnect or a late subscriber gets the stored <code>llm</code> step instead, never the deltas it missed. Only the replica executing the run has them; a stream served by another replica sees the steps through its store poll and no deltas.</p><p>To resume, send <code>Last-Event-ID</code> with the last step id you saw, or the query <code>?after=&lt;step index&gt;</code> (a non-negative integer, else 400). If both are present, a valid <code>Last-Event-ID</code> wins: it is the client&#39;s progress on a reconnect, while the URL stays the one of the first connect.</p><p>The stream takes bearer tokens only, and browser <code>EventSource</code> cannot send an <code>Authorization</code> header. In a browser, read the stream with a fetch-based SSE reader (<code>fetch</code> plus an SSE parser over the response body) that sends <code>Authorization</code> and, on reconnect, <code>Last-Event-ID</code> (or <code>?after=</code>).</p><p>An app holds at most <code>stream.maxOpen</code> (1000) open streams plus waiting MCP <code>run_&lt;agent&gt;</code> calls, on one counter. Over the cap a stream answers 503 with <code>Retry-After: 5</code>; retry after that many seconds.</p><h2 id="authentication-and-permissions" tabindex="-1">Authentication and permissions <a class="header-anchor" href="#authentication-and-permissions" aria-label="Permalink to &quot;Authentication and permissions&quot;">​</a></h2><p><code>auth</code> takes one authenticator or a chain; the first principal wins. A resolved principal needs a non-empty <code>id</code> and <code>kind</code> and a <code>permissions</code> array of strings; anything else is a server misconfiguration (500, reported to <code>onError</code>) and ends the chain.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> ciToken = process.env.CI_TOKEN;</span></span>
<span class="line"><span style="color:#FF7B84;">return</span><span style="color:#E6DFDE;"> [</span></span>
<span class="line"><span style="color:#958A8B;">    // CI and service accounts: tokens of at least 16 characters.</span></span>
<span class="line"><span style="color:#958A8B;">    // Static tokens go first: authup() in remote mode introspects every non-JWT bearer.</span></span>
<span class="line"><span style="color:#E6DFDE;">    ...(ciToken ?</span></span>
<span class="line"><span style="color:#E6DFDE;">        [staticTokens({</span></span>
<span class="line"><span style="color:#E6DFDE;">            tokens: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">                value: ciToken,</span></span>
<span class="line"><span style="color:#E6DFDE;">                id: </span><span style="color:#E7C58C;">&#39;ci&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                permissions: [</span><span style="color:#E7C58C;">&#39;agent:deploy:run&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;run:read&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#E6DFDE;">            }],</span></span>
<span class="line"><span style="color:#E6DFDE;">        })] :</span></span>
<span class="line"><span style="color:#E6DFDE;">        []),</span></span>
<span class="line"><span style="color:#958A8B;">    // authup: grants come from global tokens, verified remotely</span></span>
<span class="line"><span style="color:#E6DFDE;">    authup({ verifier }),</span></span>
<span class="line"><span style="color:#958A8B;">    // GitHub Actions OIDC: the mapper decides which repository gets which grants</span></span>
<span class="line"><span style="color:#E6DFDE;">    oidc({</span></span>
<span class="line"><span style="color:#E6DFDE;">        issuers: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">            id: </span><span style="color:#E7C58C;">&#39;github-actions&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            issuer: </span><span style="color:#E7C58C;">&#39;https://token.actions.githubusercontent.com&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            audience: </span><span style="color:#E7C58C;">&#39;chamvi&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        }],</span></span>
<span class="line"><span style="color:#E6DFDE;">        principal: ({ claims }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> (claims.repository === </span><span style="color:#E7C58C;">&#39;acme/infra&#39;</span><span style="color:#E6DFDE;"> ?</span></span>
<span class="line"><span style="color:#E6DFDE;">            {</span></span>
<span class="line"><span style="color:#E6DFDE;">                id: </span><span style="color:#E7C58C;">\`gha:</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">String</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">claims</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">sub</span><span style="color:#E6DFDE;">)</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                kind: </span><span style="color:#E7C58C;">&#39;oidc&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                permissions: [</span><span style="color:#E7C58C;">&#39;agent:deploy:run&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#E6DFDE;">            } :</span></span>
<span class="line"><span style="color:#FF7B84;">            undefined</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">];</span></span></code></pre></div><ul><li><code>staticTokens({ tokens: [{ value, id, permissions }] })</code>: bearer tokens (<code>value</code>, at least 16 characters, each given once), each with a non-empty <code>id</code> (the principal and run invoker id; several tokens may share one, e.g. while rotating). Put it before <code>authup()</code> and <code>oidc()</code>: <code>authup()</code> in remote mode introspects every bearer that is not a JWT, so a static token placed after it is sent to the authup server.</li><li><code>authup()</code>: authup tokens through <code>@authup/server-adapter-web</code>. Only tokens with the <code>global</code> scope grant their permissions; others authenticate and get 403. Grants need remote verification (introspection); a cached result lives until the token&#39;s <code>exp</code>.</li><li><code>oidc()</code>: any OIDC issuer through <a href="https://github.com/tada5hi/vouchly" target="_blank" rel="noreferrer">vouchly</a>. Every issuer needs an <code>audience</code>, and <code>principal</code> is required: a public issuer such as GitHub Actions lets anyone mint a token for your audience, so the mapper decides which claims get which grants. A mapper result without a non-empty <code>id</code> and <code>kind</code> and a <code>permissions</code> array of strings is a server error (500, reported to <code>onError</code>), not a client one.</li></ul><table tabindex="0"><thead><tr><th>Permission</th><th>Grants</th></tr></thead><tbody><tr><td><code>agent:&lt;name&gt;:run</code></td><td>Start the agent&#39;s runs and read them</td></tr><tr><td><code>agent:&lt;name&gt;:approve</code></td><td>Answer the agent&#39;s approvals (<code>POST /runs/:id/approve</code>, MCP <code>approve_run</code>)</td></tr><tr><td><code>run:read</code></td><td>Read and list every run, agents and schedules</td></tr><tr><td><code>run:cancel</code></td><td>Cancel runs</td></tr><tr><td><code>state:read</code>, <code>state:write</code></td><td>Agent state</td></tr><tr><td><code>tool:&lt;agent&gt;:&lt;tool&gt;</code></td><td>Read by <code>requireToolPermission()</code>: the agent offers the tool to this principal&#39;s runs</td></tr><tr><td><code>*</code></td><td>Everything</td></tr></tbody></table><p>A <code>*</code> segment matches exactly one segment (<code>agent:*:run</code>). A client that may start an agent&#39;s runs can follow them without <code>run:read</code>, but to list runs it must filter to that agent.</p><p><code>POST /runs/:id/approve</code> needs the approve permission for the run&#39;s agent (no read permission); it loads the run (404), checks the permission (403) and only then reads the body, and passes the <code>approvalId</code> it was shown, so a stale or concurrent answer is a 409 rather than an answer to a newer call.</p><h2 id="invoker" tabindex="-1">Invoker <a class="header-anchor" href="#invoker" aria-label="Permalink to &quot;Invoker&quot;">​</a></h2><p><code>POST /agents/:name/runs</code> and MCP <code>run_&lt;agent&gt;</code> record the authenticated principal as the run&#39;s invoker (<code>run.trigger.invoker</code>): its <code>id</code>, <code>kind</code>, <code>permissions</code> and a <code>name</code> from the <code>name</code> or <code>preferred_username</code> claim (never <code>email</code>, since every reader of the run sees the name; static tokens have no name). An agent&#39;s <a href="/guide/tools#restricting-tools-per-invoker"><code>toolPolicy</code></a> and tool code read it. <code>POST /runs/:id/approve</code> and MCP <code>approve_run</code> record the principal that answered as the <code>wait</code> step&#39;s <code>output.approver</code>. Webhook and GitHub runs have no invoker, and neither ever comes from a request body.</p><p>The invoker is a snapshot: a run keeps the grants it was started with, even when a grant is revoked while it waits on an approval. Responses (REST, SSE, MCP) carry the invoker and the approver without their <code>permissions</code>, so a <code>run:read</code> holder never learns another principal&#39;s grants.</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><code>/mcp</code> is a streamable HTTP endpoint (MCP TypeScript SDK v2; 2025-era clients are served statelessly), authenticated like REST. Each client sees the tools its principal may use:</p><ul><li><code>run_&lt;agent&gt;</code> for each agent with <code>http.on()</code> it may run (runs carry channel <code>mcp</code>): <code>{ payload?, idempotencyKey?, address?, waitSeconds? }</code>. With <code>waitSeconds</code> (capped by <code>mcp.maxWaitSeconds</code>, default 60) it waits for <code>completed</code>, <code>failed</code>, <code>cancelled</code> or <code>waiting</code> and returns the output, the error or the pending approval. A wait counts against <code>stream.maxOpen</code>: over the cap the call does not wait and answers at once with <code>{ runId, status, deduplicated }</code>, as with <code>waitSeconds: 0</code>; the run is already dispatched and goes on.</li><li><code>get_run</code>, <code>list_runs</code>: the REST read rule applies.</li><li><code>approve_run</code>: <code>{ runId, approvalId, approved, reason? }</code> (the <code>approvalId</code> of the run&#39;s <code>waiting</code>, from <code>get_run</code>), with the approve permission.</li></ul><p>An MCP start dedupes its <code>idempotencyKey</code> under <code>&lt;agent&gt;:mcp:&lt;kind&gt;:&lt;id&gt;</code>, a REST start under <code>&lt;agent&gt;:http:&lt;kind&gt;:&lt;id&gt;</code> (the principal&#39;s <code>kind</code> and <code>id</code>, URI-encoded): one key used over both transports, or by two principals, creates two runs. A client registers the endpoint like any HTTP MCP server:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// OpenClaw (or any MCP client) lists the app as a streamable HTTP server</span></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> mcpServers = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    chamvi: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        type: </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        url: </span><span style="color:#E7C58C;">&#39;http://chamvi.agents.svc/api/mcp&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        headers: { Authorization: </span><span style="color:#E7C58C;">&#39;Bearer \${CHAMVI_TOKEN}&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span></code></pre></div><p>This is the &quot;MCP in&quot; half of the <a href="/deployment/openclaw">OpenClaw</a> integration.</p><h2 id="extra-routes" tabindex="-1">Extra routes <a class="header-anchor" href="#extra-routes" aria-label="Permalink to &quot;Extra routes&quot;">​</a></h2><p><code>routes</code> adds routes that other packages provide, served under <code>basePath</code> beside the built-in ones. A route is a static path with a method and a fetch-style handler: it gets the request (URL, method, headers and signal, without the body) and a <code>readBody()</code> that returns the raw bytes (the app&#39;s <code>bodyLimit</code>, 413 and 415 apply; repeated calls return the same bytes), and answers <code>{ status, body? }</code> (an object, array, number or boolean as JSON, a string as <code>text/plain</code>, no <code>body</code> or <code>null</code> as an empty body). Extra routes are not authenticated by <code>auth</code>: they check their own credentials. Intake of runs belongs in a <a href="/guide/channels">channel</a> (the <code>/channels/&lt;name&gt;</code> mount), not in an extra route. Thrown errors render like those of every other route. <code>rateLimit: false</code> takes a route out of the rate limit, for senders that never retry a refused request. Paths match case-insensitively, like routup&#39;s routing: a route may not differ from a built-in segment or another route only by case.</p><p>A route can also answer headers and bytes: <code>headers</code> is set on the response (a <code>content-type</code> there wins over the body&#39;s default) and a <code>Uint8Array</code> body is sent as is (<code>application/octet-stream</code> unless <code>headers</code> names a type), with the CORS and rate limit headers kept. <code>prefix: true</code> makes the route serve its <code>path</code> and everything below <code>path/</code> for its method (a static file server, such as a dashboard&#39;s assets): the handler reads the rest as <code>request.subpath</code> (<code>&#39;&#39;</code> for the path itself, else the raw, still percent-encoded rest with its case, never the query), and metrics label it <code>&lt;path&gt;/*</code>. A route of the same method at or under a prefix route, or a prefix route at or above the metrics path, is refused at construction. The route context carries the app&#39;s <code>basePath</code> to build links with.</p><p><code>@chamvi/ui</code> is such a route: <code>routes: uiRoutes()</code> serves the <a href="/guide/ui">dashboard</a> at <code>/ui</code>.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><ul><li><code>/metrics</code> is unauthenticated: keep it off the public ingress (a NetworkPolicy, or an internal listener) or set <code>metrics: false</code>. Each app has its own <code>prom-client</code> registry, labelled by route template (<code>/runs/:id</code>, <code>/runs/:id/artifacts/:artifactId</code>; unknown paths share <code>/_unmatched</code>); SSE streams and rate-limited requests are not timed.</li><li>The rate limit (300 requests per minute per client, health, metrics and CORS preflights excluded) keys on the socket address. Behind a reverse proxy set <code>trustProxy</code>, or every client shares the proxy&#39;s bucket; <code>X-Forwarded-For</code> is never trusted otherwise.</li><li>CORS is off unless <code>cors</code> is given.</li><li><code>/readyz</code> fails while shutting down, while the engine drains and when the store does not answer within <code>readyTimeoutMs</code> (2 s).</li></ul><h2 id="shutdown" tabindex="-1">Shutdown <a class="header-anchor" href="#shutdown" aria-label="Permalink to &quot;Shutdown&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// fail readiness, end streams, stop the channels, drain</span></span>
<span class="line"><span style="color:#E6DFDE;">process.once(</span><span style="color:#E7C58C;">&#39;SIGTERM&#39;</span><span style="color:#E6DFDE;">, () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    void</span><span style="color:#E6DFDE;"> shutdown.shutdown().then(() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> process.exit(</span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;">));</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>createShutdown()</code> fails readiness, waits <code>readinessDelayMs</code> for load balancers, runs the <code>onShutdown</code> callbacks (the app ends its SSE streams and <code>run_&lt;agent&gt;</code> waits, which answer with the run id, and closes MCP there; new streams and MCP requests then answer 503), stops accepting connections, drains the engine (which stops every channel first, then waits <code>drainTimeoutMs</code>, 30 s, for the runs) and waits at most <code>closeTimeoutMs</code> (5 s) for open connections before closing them. Every call returns the same promise. Pass <code>gracefulShutdown: false</code> to <code>serve()</code> so srvx does not handle the signal itself.</p>`,48)])])}const y=s(o,[["render",c]]);export{u as __pageData,y as default};
